async def execute(self, job, greeting):
    url = validate_job_url(job["url"], self.allowed_domains)
    page = await self._open_page(url)
    state = await self._inspect(page)

    if state["risk_detected"]:
        return self._failure("页面触发登录、验证或风控")

    target = await self._find_apply_target(page)
    if target is None:
        return self._failure("未找到明确操作入口")

    await self._fill_greeting(page, greeting)
    await target.click()
    final_state = await self._inspect(page)

    if final_state["risk_detected"]:
        return self._failure("操作后出现验证或风控")
    if not final_state["success_detected"]:
        return self._failure("页面没有明确成功状态")

    return {"ok": True, "evidence": final_state["success_evidence"]}

def parse_action(payload, now):
    action_type = parse_type(payload.get("type"))

    if action_type == "set_reminder":
        trigger_at = parse_datetime(payload.get("trigger_at"))
        latest = now + timedelta(days=365)
        if trigger_at is None or not now < trigger_at <= latest:
            return no_action()
        return reminder(trigger_at, clean_label(payload.get("label")))

    if action_type == "start_pomodoro":
        minutes = payload.get("minutes")
        if isinstance(minutes, bool) or not isinstance(minutes, int):
            return no_action()
        if not 1 <= minutes <= 120:
            return no_action()
        return pomodoro(minutes)

    if action_type == "stop_timer":
        return stop_timer()

    return no_action()

def rrf_fusion(semantic_results, bm25_results, k=60):
    scores = {}

    for rank, (doc, _) in enumerate(semantic_results, start=1):
        chunk_id = doc.metadata.get("chunk_id", doc.page_content)
        scores[chunk_id] = (doc, SEMANTIC_WEIGHT / (k + rank))

    for rank, (doc, _) in enumerate(bm25_results, start=1):
        chunk_id = doc.metadata.get("chunk_id", doc.page_content)
        previous = scores.get(chunk_id, (doc, 0.0))[1]
        scores[chunk_id] = (
            doc,
            previous + BM25_WEIGHT / (k + rank),
        )

    return sorted(
        scores.values(),
        key=lambda item: item[1],
        reverse=True,
    )

def build_report(text):
    matched, missing = extract_matches(text)
    score = round(len(matched) / len(SKILL_KEYWORDS) * 100)

    return MatchReport(
        score=score,
        matched=matched,
        missing=missing,
        resume_bullets=build_resume_suggestions(matched),
        interview_questions=build_questions(missing),
    )
